def transform(g):
    h,w=len(g),len(g[0])
    # collect color per diagonal d=c-r
    col={}
    for r in range(h):
        for c in range(w):
            if g[r][c]!=0:
                d=(c-r)
                if d in col and col[d]!=g[r][c]: return None
                col[d]=g[r][c]
    # find minimal period P with no conflicts
    ds=list(col)
    for P in range(1,30):
        m={}
        ok=True
        for d in ds:
            r=d%P
            if r in m and m[r]!=col[d]: ok=False;break
            m[r]=col[d]
        if ok: break
    return [[col.get((c-r)%P,0) for c in range(w)] for r in range(h)]

